tRecurrence,\n        updateAllPossibilities,\n        newEditEventData,\n        oldEditEventData,\n        originalEditEventData,\n        inviteActions: updatedInviteActions,\n        isInvitation,\n        sendIcs,\n        selfAttendeeToken,\n    });\n    const successText = getRecurringEventUpdatedText(saveType, saveInviteActions);\n\n    return {\n        syncActions: multiSyncActions,\n        updatePartstatActions,\n        updatePersonalPartActions,\n        texts: { success: successText },\n        sendActions,\n        hasStartChanged,\n    };\n};\n\nexport default getSaveEventActions;\n","import { VcalVeventComponent } from '@proton/shared/lib/interfaces/calendar/VcalModel';\nimport { getDateOrDateTimeProperty } from '@proton/shared/lib/calendar/vcalConverter';\nimport { getHasDtend, getIsPropertyAllDay } from '@proton/shared/lib/calendar/vcalHelper';\nimport { addDays } from '@proton/shared/lib/date-fns-utc';\nimport { CalendarEventRecurring } from '../../../interfaces/CalendarEvents';\n\n// Merge the start and end of the occurrence into the dtstart and dtend of the original event component\nconst withOccurrenceEvent = (vevent: VcalVeventComponent, recurring: CalendarEventRecurring): VcalVeventComponent => {\n    const withOccurrenceDtstart = getDateOrDateTimeProperty(vevent.dtstart, recurring.localStart);\n    if (!getHasDtend(vevent)) {\n        return { ...vevent, dtstart: withOccurrenceDtstart };\n    }\n    // Add the non-inclusive end for all-day events...\n    const safeEnd = getIsPropertyAllDay(vevent.dtend) ? addDays(recurring.localEnd, 1) : recurring.localEnd;\n    return {\n        ...vevent,\n        dtstart: withOccurrenceDtstart,\n        dtend: getDateOrDateTimeProperty(vevent.dtend, safeEnd),\n    };\n};\n\nexport default withOccurrenceEvent;\n","import {\n    convertUTCDateTimeToZone,\n    convertZonedDateTimeToUTC,\n    fromUTCDate,\n    toUTCDate,\n} from '@proton/shared/lib/date/timezone';\nimport { differenceInHours } from 'date-fns';\nimport { max } from '@proton/shared/lib/date-fns-utc';\nimport { Calendar as tsCalendar, EventModel } from '@proton/shared/lib/interfaces/calendar';\n\nimport { getTimeInUtc, getDateTimeState } from '../../components/eventModal/eventForm/time';\nimport getFrequencyModelChange from '../../components/eventModal/eventForm/getFrequencyModelChange';\nimport { CalendarViewEvent, CalendarViewEventTemporaryEvent } from './interface';\n\nexport const getCalendarViewEventProperties = ({ start, end, isAllDay }: EventModel, tzid: string) => {\n    const utcStart = getTimeInUtc(start, isAllDay);\n    const utcEnd = getTimeInUtc(end, isAllDay);\n\n    const calendarStart = isAllDay ? utcStart : toUTCDate(convertUTCDateTimeToZone(fromUTCDate(utcStart), tzid));\n    const calendarEnd = isAllDay ? utcEnd : toUTCDate(convertUTCDateTimeToZone(fromUTCDate(utcEnd), tzid));\n    const isAllPartDay = !isAllDay && differenceInHours(utcEnd, utcStart) >= 24;\n\n    return {\n        start: calendarStart,\n        end: max(calendarStart, calendarEnd),\n        isAllDay: isAllDay || isAllPartDay,\n        isAllPartDay,\n        isRecurring: false,\n    };\n};\n\nconst modelToEventProperties = (\n    oldTemporaryEvent: CalendarViewEventTemporaryEvent | undefined,\n    model: EventModel,\n    tzid: string\n) => {\n    // If unrelevant things were changed, like title or description\n    if (\n        oldTemporaryEvent &&\n        oldTemporaryEvent.tmpData &&\n        oldTemporaryEvent.tmpData.start === model.start &&\n        oldTemporaryEvent.tmpData.end === model.end &&\n        oldTemporaryEvent.tmpData.isAllDay === model.isAllDay\n    ) {\n        return;\n    }\n    return getCalendarViewEventProperties(model, tzid);\n};\n\nexport const getCreateTemporaryEvent = (\n    Calendar: tsCalendar,\n    model: EventModel,\n    tzid: string\n): CalendarViewEventTemporaryEvent => {\n    return {\n        id: 'tmp',\n        data: {\n            calendarData: Calendar,\n        },\n        ...getCalendarViewEventProperties(model, tzid),\n        tmpData: model,\n        tmpDataOriginal: model,\n    };\n};\n\nexport const getEditTemporaryEvent = (\n    targetEvent: CalendarViewEventTemporaryEvent | CalendarViewEvent,\n    model: EventModel,\n    tzid: string\n): CalendarViewEventTemporaryEvent => {\n    const { id, data } = targetEvent;\n    return {\n        id: 'tmp',\n        targetId: (targetEvent as CalendarViewEventTemporaryEvent).targetId || id,\n        data,\n        ...getCalendarViewEventProperties(model, tzid),\n        tmpData: model,\n        tmpDataOriginal: model,\n        tmpOriginalTarget: targetEvent,\n    };\n};\n\nexport const getTemporaryEvent = (\n    temporaryEvent: CalendarViewEventTemporaryEvent,\n    model: EventModel,\n    tzid: string\n): CalendarViewEventTemporaryEvent => {\n    const tmpDataOriginal = temporaryEvent.tmpDataOriginal || model;\n\n    return {\n        ...temporaryEvent,\n        ...modelToEventProperties(temporaryEvent, model, tzid),\n        tmpData: model,\n        tmpDataOriginal,\n    };\n};\n\nexport const getTimeInTimezone = (fakeUtcDate: Date, fromTzid: string, toTzid: string) => {\n    const trueUtcTime = convertZonedDateTimeToUTC(fromUTCDate(fakeUtcDate), fromTzid);\n    return toUTCDate(convertUTCDateTimeToZone(trueUtcTime, toTzid));\n};\n\ninterface GetUpdateDateTimeArguments {\n    start: Date;\n    end: Date;\n    isAllDay: boolean;\n    tzid: string;\n}\nexport const getUpdatedDateTime = (\n    oldModel: EventModel,\n    { start, end, isAllDay, tzid: fromTzid }: GetUpdateDateTimeArguments\n): EventModel => {\n    const tzStart = oldModel.start.tzid;\n    const tzEnd = oldModel.end.tzid;\n\n    // If there is a timezone, convert the fake UTC time in the timezone of the calendar to the specified timezone\n    const utcStart = tzStart !== fromTzid ? getTimeInTimezone(start, fromTzid, tzStart) : start;\n    const utcEnd = tzEnd !== fromTzid ? getTimeInTimezone(end, fromTzid, tzEnd) : end;\n    const newStart = getDateTimeState(utcStart, tzStart);\n    const newEnd = getDateTimeState(utcEnd, tzEnd);\n\n    return {\n        ...oldModel,\n        isAllDay,\n        start: newStart,\n        end: newEnd,\n        frequencyModel: getFrequencyModelChange(oldModel.start, newStart, oldModel.frequencyModel),\n    };\n};\n","import { API_CODES } from '@proton/shared/lib/constants';\nimport {\n    SyncMultipleApiResponse,\n    SyncMultipleApiResponses,\n    UpdateEventPartApiResponse,\n} from '@proton/shared/lib/interfaces/calendar';\nimport { UpdatePartstatOperation, UpdatePersonalPartOperation } from '../../../../interfaces/Invite';\nimport upsertCalendarApiEvent from './upsertCalendarApiEvent';\nimport { getIsDeleteSyncOperation, SyncEventActionOperations } from '../../getSyncMultipleEventsPayload';\nimport { CalendarsEventsCache } from '../interface';\nimport removeCalendarEventStoreRecord from './removeCalendarEventStoreRecord';\n\nconst getResponse = (responses: SyncMultipleApiResponses[], index: number) => {\n    return responses.find((x) => x.Index === index);\n};\n\nexport const upsertSyncMultiActionsResponses = (\n    multiActions: SyncEventActionOperations[],\n    multiResponses: SyncMultipleApiResponse[],\n    calendarsEventsCache: CalendarsEventsCache\n) => {\n    for (let i = 0; i < multiResponses.length; ++i) {\n        const actions = multiActions[i];\n        const responses = multiResponses[i];\n\n        const responsesArray = responses?.Responses;\n        const calendarEventsCache = calendarsEventsCache.calendars[actions.calendarID];\n\n        if (!Array.isArray(responsesArray) || !calendarEventsCache) {\n            continue;\n        }\n\n        for (let j = 0; j < actions.operations.length; ++j) {\n            const operation = actions.operations[j];\n            const matchingResponse = getResponse(responsesArray, j);\n\n            if (getIsDeleteSyncOperation(operation)) {\n                if (!matchingResponse || matchingResponse.Response.Code =