                              ...tmpData,\n                                                  // This is used to keep track of the original event start\n                                                  initialDate: propertyToUTCDate(\n                                                      modelToDateProperty(tmpData.start, tmpData.isAllDay)\n                                                  ),\n                                                  organizer: undefined,\n                                                  isOrganizer: true,\n                                              },\n                                              isDuplicating: true,\n                                          });\n                                      }\n                            }\n                            onChangePartstat={async (partstat: ICAL_ATTENDEE_STATUS) => {\n                                if (!targetEvent) {\n                                    return;\n                                }\n                                const newTemporaryModel = getUpdateModel({\n                                    viewEventData: targetEvent.data,\n                                    emailNotificationsEnabled,\n                                    partstat,\n                                });\n                                if (!newTemporaryModel) {\n                                    return;\n                                }\n                                const inviteActions = {\n                                    isProtonProtonInvite: newTemporaryModel.isProtonProtonInvite,\n                                    type: INVITE_ACTION_TYPES.CHANGE_PARTSTAT,\n                                    partstat,\n                                    selfAddress: newTemporaryModel.selfAddress,\n                                    selfAttendeeIndex: newTemporaryModel.selfAttendeeIndex,\n                                };\n\n                                const newTemporaryEvent = getTemporaryEvent(\n                                    getEditTemporaryEvent(targetEvent, newTemporaryModel, tzid),\n                                    newTemporaryModel,\n                                    tzid\n                                );\n                                return handleSaveEvent(newTemporaryEvent, inviteActions);\n                            }}\n                            onClose={handleCloseEventPopover}\n                        />\n                    );\n                }}\n            </Popover>\n            <Popover containerEl={document.body} targetEl={targetMoreRef} isOpen={!!targetMoreData} once>\n                {({ style, ref }: PopoverRenderData) => {\n                    if (!targetMoreData) {\n                        return null;\n                    }\n                    return (\n                        <MorePopoverEvent\n                            tzid={tzid}\n                            isNarrow={isNarrow}\n                            style={style}\n                            popoverRef={ref}\n                            now={now}\n                            date={targetMoreData.date}\n                            events={targetMoreEvents}\n                            targetEventRef={setTargetEventRef}\n                            targetEventData={targetEventData}\n                            formatTime={formatTime}\n                            onClickEvent={handleClickEvent}\n                            onClose={handleCloseMorePopover}\n                        />\n                    );\n                }}\n            </Popover>\n            <Prompt\n                message={(location) => {\n                    if (isInTemporaryBlocking && location.pathname.includes('settings')) {\n                        handleConfirmDeleteTemporary({ ask: true }).then(closeAllPopovers).catch(noop);\n                        return false;\n                    }\n                    return true;\n                }}\n            />\n\n            {!!tmpData && (\n                <CreateEventModal\n                    isNarrow={isNarrow}\n                    displayWeekNumbers={displayWeekNumbers}\n                    weekStartsOn={weekStartsOn}\n                    tzid={tzid}\n                    model={tmpData}\n                    setModel={handleSetTemporaryEventModel}\n                    isDuplicating={isDuplicatingEvent}\n                    isOpen={createEventModal.isOpen}\n                    onSave={async (inviteActions: InviteActions) => {\n                        if (!temporaryEvent) {\n                            return Promise.reject(new Error('Undefined behavior'));\n                        }\n\n                        try {\n                            await handleSaveEvent(temporaryEvent, inviteActions, isDuplicatingEvent);\n\n                            // close modal clearing props\n                            updateModal('createEventModal', {\n                                isOpen: false,\n                            });\n                        } catch (error) {\n                            return noop();\n                        }\n                    }}\n                    onDelete={async (inviteActions) => {\n                        if (!temporaryEvent?.data?.eventData || !temporaryEvent.tmpOriginalTarget) {\n                            return Promise.reject(new Error('Undefined behavior'));\n                        }\n\n                        try {\n                            await handleDeleteEvent(temporaryEvent.tmpOriginalTarget, inviteActions);\n\n                            closeModal('createEventModal');\n                        } catch (error) {\n                            return noop();\n                        }\n                    }}\n                    onClose={async () => {\n                        try {\n                            await handleConfirmDeleteTemporary({ ask: true });\n                            closeModal('createEventModal');\n                        } catch (error) {\n                            return noop();\n                        }\n                    }}\n                    onExit={() => {\n                        closeAllPopovers();\n                    }}\n                    isCreateEvent={isCreatingEvent}\n                    addresses={addresses}\n                />\n            )}\n        </Dropzone>\n    );\n};\n\nexport default InteractiveCalendarView;\n","import { useState } from 'react';\n\nimport { ModalWithProps } from '@proton/shared/lib/interfaces/Modal';\n\nexport const useModalsMap = <T extends Record<string, ModalWithProps<any>>>(map: T) => {\n    const [modalsMap, setModalsMap] = useState<T>(map);\n\n    const updateModal = <K extends keyof T>(key: K, newValue: T[K]) =>\n        setModalsMap((prevState) => ({\n            ...prevState,\n            [key]: newValue,\n        }));\n\n    const closeModal = (key: keyof T) =>\n        setModalsMap((prevState) => ({\n            ...prevState,\n            [key]: {\n                isOpen: false,\n            },\n        }));\n\n    return { modalsMap, closeModal, setModalsMap, updateModal };\n};\n","import { MutableRefObject } from 'react';\nimport { differenceInCalendarDays } from '@proton/shared/lib/date-fns-utc';\nimport { EventTargetAction } from './interface';\nimport { TYPE } from '../../components/calendar/interactions/constants';\n\nexport const getInitialTargetEventData = (\n    eventTargetActionRef: MutableRefObject<EventTargetAction | undefined>,\n    dateRange: [Date, Date]\n) => {\n    const eventTargetAction = eventTargetActionRef.current;\n    if (!eventTargetAction) {\n        return;\n    }\n\n    const { id, isAllDay, isAllPartDay, startInTzid } = eventTargetAction;\n\n    const isDayGrid = isAllDay || isAllPartDay;\n    const [startDateRange, endDateRange] = dateRange;\n\n    const getTimeGridIdx = () => {\n        if (startDateRange > startInTzid || startInTzid > endDateRange) {\n            return 0;\n        }\n        return differenceInCalendarDays(startInTzid, startDateRange);\n    };\n\n    return {\n        targetEventData: {\n            id,\n            type: isDayGrid ? TYPE.DAYGRID : TYPE.TIMEGRID,\n            // Assuming week view is always displayed, so not trying to calculate the idx\n            idx: isDayGrid ? 0 : getTimeGridIdx(),\n        },\n    };\n};\n","import { ACTIONS, TYPE } from './constants';\nimport { CalendarViewEvent } from '../../../containers/calendar/interface';\n\nexport interface EventDownAction {\n    action: ACTIONS.EVENT_DOWN;\n    payload: {\n        type: TYPE;\n        idx: number;\n        event: CalendarViewEvent;\n    };\n}\n\nexport interface CreateDownAction {\n    action: ACTIONS.CREATE_DOWN;\n    payload: {\n        type: TYPE;\n        idx: number | Date;\n    };\n}\n\nexport interface MoreDownAction {\n    action: ACTIONS.MORE_DOWN;\n    payload: {\n        type: TYPE;\n        date: Date;\n        events: Set<string>;\n        idx: number;\n        row: number;\n    };\n}\n\nexport type MouseDownAction = MoreDownAction | EventDownAction | CreateDownAction;\n\nexport const isMoreDownAction = (action: MouseDownAction): action is MoreDownAction => {\n    return action.action === ACTIONS.MORE_DOWN;\n};\nexport const isEventDownAction = (action: MouseDownAction): action is EventDownAction => {\n    return action.action === ACTIONS.EVENT_DOWN;\n};\nexport const isCreateDownAction = (action: MouseDownAction): action is CreateDownAction => {\n    return action.action === ACTIONS.CREATE_DOWN;\n};\n\nexport interface MoreUpAction {\n    action: ACTIONS.MORE_UP;\n}\nexport interface EventUpAction {\n    action: ACTIONS.EVENT_UP;\n    payload: {\n        type: TYPE;\n        idx: number;\n        event?: CalendarViewEvent;\n    };\n}\nexport interface StartEndResult {\n    start: Date;\n    end: Date;\n}\nexport interface EventMoveAction {\n    action: ACTIONS.EVENT_MOVE | ACTIONS.EVENT_MOVE_UP;\n    payload: {\n        type: TYPE;\n        idx?: number;\n        result: StartEndResult;\n        day?: number;\n    };\n}\nexport interface CreateUpAction {\n    action: ACTIONS.CREATE_UP | ACTIONS.CREATE_MOVE | ACTIONS.CREATE_MOVE_UP;\n    payload: {\n        type: TYPE;\n        idx: number;\n        result: StartEndResult;\n    };\n}\n\nexport type MouseUpAction = MoreUpAction | EventUpAction | EventMoveAction | CreateUpAction;\n\nexport type OnMouseDown = (action: MouseDownAction) => undefined | ((action: MouseUpAction) => void);\n","import { MAXIMUM_DATE_UTC, MINIMUM_DATE_UTC, VIEWS } from '@proton/shared/lib/calendar/constants';\nimport {\n    getAutoDetectPrimaryTimezone,\n    getDefaultTzid,\n    getDefaultView,\n    getDisplaySecondaryTimezone,\n    getDisplayWeekNumbers,\n    getInviteLocale,\n    getSecondaryTimezone,\n} from '@proton/shared/lib/calendar/getSettings';\nimport { isSameDay, MILLISECONDS_IN_MINUTE } from '@proton/shared/lib/date-fns-utc';\nimport {\n    convertUTCDateTimeToZone,\n    convertZonedDateTimeToUTC,\n    formatGMTOffsetAbbreviation,\n    fromUTCDate,\n    getTimezone,\n    getTimezoneOffset,\n    toUTCDate,\n} from '@proton/shared/lib/date/timezone';\nimport { Address, User, UserSettings } from '@proton/shared/lib/interfaces';\nimport { AttendeeModel, Calendar, CalendarUserSettings } from '@proton/shared/lib/interfaces/calendar';\nimport { getWeekStartsOn } from '@proton/shared/lib/settings/helper';\nimport { MutableRefObject, useCallback, useEffect, useMemo, useReducer, useRef, useState } from 'react';\nimport { useAppTitle, useCalendarBootstrap } from '@proton/components';\nimport { useHistory, useLocation } from 'react-router-dom';\nimport { unary } from '@proton/shared/lib/helpers/function';\nimport { getIsPersonalCalendar } from '@proton/shared/lib/calendar/subscribe/helpers';\nimport {\n    canAskTimezoneSuggestion,\n    getTimezoneSuggestionKey,\n    saveLastTimezoneSuggestion,\n} from '../../helpers/timezoneSuggestion';\nimport AskUpdateTimezoneModal from '../settings/AskUpdateTimezoneModal';\nimport CalendarContainerView from './CalendarContainerView';\nimport ContactEmailsProvider from './ContactEmailsProvider';\nimport { CalendarsEventsCache } from './eventStore/interface';\nimport useCalendarsEvents from './eventStore/useCalendarsEvents';\nimport getDateRange from './getDateRange';\nimport getTitleDateString from './getTitleDateString';\nimport { fromUrlParams, toUrlParams } from './getUrlHelper';\nimport InteractiveCalendarView from './InteractiveCalendarView';\nimport { EventTargetAction, InteractiveRef, TimeGridRef } from './interface';\n\nconst { DAY, WEEK, MONTH } = VIEWS;\n\nconst SUPPORTED_VIEWS = [MONTH, WEEK, DAY];\n\nconst getRange = (view: VIEWS, range: number) => {\n    if (!range) {\n        return;\n    }\n    const max = Math.max(Math.min(range, 6), 1);\n    if (view === WEEK) {\n        return max;\n    }\n    return Math.min(max, 5);\n};\n\nconst customReducer = (oldState: { [key: string]: any }, newState: { [key: string]: any }) => {\n    const keys = Object.keys(newState);\n    for (const key of keys) {\n        // If there is a difference in any of the keys, return a new object.\n        if (oldState[key] !== newState[key]) {\n            return {\n                ...oldState,\n                ...newState,\n            };\n        }\n    }\n    // Otherwise return the old state to prevent a re-render\n    return oldState;\n};\n\ninterface Props {\n    tzid: string;\n    setCustomTzid: (tzid: string) => void;\n    isNarrow: boolean;\n    user: User;\n    addresses: Address[];\n    activeAddresses: Address[];\n    visibleCalendars: Calendar[];\n    activeCalendars: Calendar[];\n    calendars: Calendar[];\n    defaultCalendar?: Calendar;\n    userSettings: UserSettings;\n    calendarUserSettings: CalendarUserSettings;\n    calendarsEventsCacheRef: MutableRefObject<CalendarsEventsCache>;\n    eventTargetActionRef: MutableRefObject<EventTargetAction | undefined>;\n}\n\nconst CalendarContainer = ({\n    tzid,\n    setCustomTzid,\n    isNarrow,\n    user,\n    addresses,\n    activeAddresses,\n    calendars,\n    activeCalendars,\n    visibleCalendars,\n    defaultCalendar,\n    userSettings,\n    calendarUserSettings,\n    calendarsEventsCacheRef,\n    eventTargetActionRef,\n}: Props) => {\n    const history = useHistory();\n    const location = useLocation();\n    const [disableCreate, setDisableCreate] = useState(false);\n    const [isAskUpdateTimezoneModalOpen, setIsAskUpdateTimezoneModalOpen] = useState(false);\n\n    const interactiveRef = useRef<InteractiveRef>(null);\n    const timeGridViewRef = useRef<TimeGridRef>(null);\n\n    const [nowDate, setNowDate] = useState(() => new Date());\n    const [localTimezoneId, setLocalTimezoneId] = useState<string>();\n\n    useEffect(() => {\n        const handle = setInterval(() => setNowDate(new Date()), 30000);\n        return () => {\n            clearInterval(handle);\n        };\n    }, []);\n\n    useEffect(() => {\n        return () => {\n            setCustomTzid('');\n        };\n    }, []);\n\n    const {\n        view: urlView,\n        range: urlRange,\n        date: urlDate,\n    } = useMemo(() => fromUrlParams(location.pathname), [location.pathname]);\n\n    // In the same to get around setStates not being batched in the range selector callback.\n    const [{ view: customView, range: customRange, date: customUtcDate }, setCustom] = useReducer(\n        customReducer,\n        undefined,\n        () => {\n            return { view: urlView, range: urlRange, date: urlDate };\n        }\n    );\n\n    useEffect(() => {\n        // We only care about new dates in the URL when the browser moves back or forward, not from push states coming from the app.\n        if (history.action === 'POP') {\n            setCustom({ view: urlView, range: urlRange, date: urlDate });\n        }\n    }, [urlDate, urlView, urlRange]);\n\n    useEffect(() => {\n        const hasAutoDetectPrimaryTimezone = getAutoDetectPrimaryTimezone(calendarUserSettings);\n        if (!hasAutoDetectPrimaryTimezone) {\n            return;\n        }\n        const run = async () => {\n            const localTzid = getTimezone();\n            const savedTzid = getDefaultTzid(calendarUserSettings, localTzid);\n            const key = await getTimezoneSuggestionKey(user.ID);\n            if (savedTzid !== localTzid && canAskTimezoneSuggestion(key)) {\n                saveLastTimezoneSuggestion(key);\n                setIsAskUpdateTimezoneModalOpen(true);\n                setLocalTimezoneId(localTzid);\n            }\n        };\n        void run();\n    }, []);\n\n    const utcNowDateInTimezone = useMemo(() => {\n        return toUTCDate(convertUTCDateTimeToZone(fromUTCDate(nowDate), tzid));\n    }, [nowDate, tzid]);\n\n    const utcDefaultDateRef = useRef<{ prev: Date; value: Date }>();\n    // A ref is used to avoid falling on the cache purging of react\n    if (\n        !utcDefaultDateRef.current ||\n        (utcDefaultDateRef.current.prev !== utcNowDateInTimezone &&\n            !isSameDay(utcDefaultDateRef.current.value, utcNowDateInTimezone))\n    ) {\n        utcDefaultDateRef.current = {\n            prev: utcNowDateInTimezone,\n            value: new Date(\n                Date.UTC(\n                    utcNowDateInTimezone.getUTCFullYear(),\n                    utcNowDateInTimezone.getUTCMonth(),\n                    utcNowDateInTimezone.getUTCDate()\n                )\n            ),\n        };\n    }\n    const utcDefaultDate = utcDefaultDateRef.current.value;\n\n    const utcDate = customUtcDate || utcDefaultDate;\n\n    const defaultView = getDefaultView(calendarUserSettings);\n    const requestedView = customView || defaultView;\n    const view = isNarrow ? WEEK : SUPPORTED_VIEWS.includes(requestedView) ? requestedView : WEEK;\n\n    const range = isNarrow ? undefined : getRange(view, customRange);\n    const weekStartsOn = getWeekStartsOn(userSettings);\n    const displayWeekNumbers = getDisplayWeekNumbers(calendarUserSettings);\n    const displaySecondaryTimezone = getDisplaySecondaryTimezone(calendarUserSettings);\n    const secondaryTzid = getSecondaryTimezone(calendarUserSettings);\n    const inviteLocale = getInviteLocale(calendarUserSettings);\n\n    const utcDateRange = useMemo(() => {\n        return getDateRange(utcDate, range, view, weekStartsOn);\n    }, [view, utcDate, weekStartsOn, range]);\n\n    const utcDateRangeInTimezone = useMemo(\n        (): [Date, Date] => [\n            toUTCDate(convertZonedDateTimeToUTC(fromUTCDate(utcDateRange[0]), tzid)),\n            toUTCDate(convertZonedDateTimeToUTC(fromUTCDate(utcDateRange[1]), tzid)),\n        ],\n        [utcDateRange, tzid]\n    );\n\n    const timezoneInformation = useMemo(() => {\n        const [startDate] = utcDateRangeInTimezone;\n        const { offset } = getTimezoneOffset(startDate, tzid);\n        const { offset: secondaryOffset } = getTimezoneOffset(startDate, secondaryTzid || tzid);\n        return {\n            primaryTimezone: `${formatGMTOffsetAbbreviation(offset)}`,\n            secondaryTimezone: `${formatGMTOffsetAbbreviation(secondaryOffset)}`,\n            secondaryTimezoneOffset: (secondaryOffset - offset) * MILLISECONDS_IN_MINUTE,\n        };\n    }, [utcDateRangeInTimezone, secondaryTzid, tzid]);\n\n    useEffect(() => {\n        const newRoute = toUrlParams({ date: utcDate, defaultDate: utcDefaultDate, view, defaultView, range });\n        if (location.pathname === newRoute) {\n            return;\n        }\n        history.push({ pathname: newRoute });\n        // Intentionally not listening to everything to only trigger URL updates when these variables change.\n    }, [view, range, utcDate]);\n\n    const calendarTitle = useMemo(() => {\n        return getTitleDateString(view, range, utcDateRange, utcDate);\n    }, [view, range, utcDate, utcDateRange]);\n\n    useAppTitle(calendarTitle);\n\n    const [initializeCacheOnlyCalendarsIDs, setInitializeCacheOnlyCalendarsIDs] = useState<string[]>([]);\n    const [calendarsEvents, loadingEvents] = useCalendarsEvents(\n        visibleCalendars,\n        utcDateRangeInTimezone,\n        tzid,\n        calendarsEventsCacheRef,\n        initializeCacheOnlyCalendarsIDs,\n        () => setInitializeCacheOnlyCalendarsIDs([])\n    );\n\n    const scrollToNow = useCallback(() => {\n        setTimeout(() => {\n            timeGridViewRef.current?.scrollToNow?.();\n        }, 10);\n    }, []);\n\n    const handleChangeView = useCallback((newView: VIEWS) => {\n        setCustom({ view: newView, range: undefined });\n        scrollToNow();\n    }, []);\n\n    const handleClickToday = useCallback(() => {\n        utcDefaultDateRef.current = undefined; // Purpose: Reset the minicalendar when clicking today multiple times\n        setCustom({ date: utcDefaultDate, range: undefined });\n        scrollToNow();\n    }, [utcDefaultDate]);\n\n    const handleChangeDate = useCallback((newDate: Date) => {\n        if (newDate < MINIMUM_DATE_UTC || newDate > MAXIMUM_DATE_UTC) {\n            return;\n        }\n        setCustom({ date: newDate });\n    }, []);\n\n    const handleChangeDateRange = useCallback((newDate: Date, numberOfDays: number, resetRange?: boolean) => {\n        if (newDate < MINIMUM_DATE_UTC || newDate > MAXIMUM_DATE_UTC) {\n            return;\n        }\n        if (numberOfDays >= 7) {\n            setCustom({\n                view: MONTH,\n                range: Math.floor(numberOfDays / 7),\n                date: newDate,\n            });\n            return;\n        }\n        setCustom({\n            view: WEEK,\n            range: resetRange ? undefined : numberOfDays,\n            date: newDate,\n        });\n    }, []);\n\n    const handleClickDateWeekView = useCallback((newDate: Date) => {\n        if (newDate < MINIMUM_DATE_UTC || newDate > MAXIMUM_DATE_UTC) {\n            return;\n        }\n        setCustom({ view: DAY, range: undefined, date: newDate });\n    }, []);\n\n    const [defaultCalendarBootstrap, loadingCalendarBootstrap] = useCalendarBootstrap(\n        defaultCalendar ? defaultCalendar.ID : undefined\n    );\n\n    const [containerRef, setContainerRef] = useState<HTMLDivElement | null>(null);\n\n    const isLoading = loadingCalendarBootstrap || loadingEvents;\n    const isEventCreationDisabled =\n        disableCreate || !defaultCalendarBootstrap || !activeCalendars.find(unary(getIsPersonalCalendar));\n\n    return (\n        <CalendarContainerView\n            calendarUserSettings={calendarUserSettings}\n            calendars={calendars}\n            onCreateCalendarFromSidebar={(id: string) => setInitializeCacheOnlyCalendarsIDs([id])}\n            isLoading={isLoading}\n            displayWeekNumbers={displayWeekNumbers}\n            weekStartsOn={weekStartsOn}\n            tzid={tzid}\n            setTzid={setCustomTzid}\n            range={range}\n            view={view}\n            isNarrow={isNarrow}\n            utcDateRangeInTimezone={utcDateRangeInTimezone}\n            utcDefaultDate={utcDefaultDate}\n            utcDate={utcDate}\n            utcDateRange={utcDateRange}\n            onCreateEvent={\n                isEventCreationDisabled\n                    ? undefined\n                    : (attendees: AttendeeModel[] = []) => interactiveRef.current?.createEvent(attendees)\n            }\n            onClickToday={handleClickToday}\n            onChangeDate={handleChangeDate}\n            onChangeDateRange={handleChangeDateRange}\n            onChangeView={handleChangeView}\n            containerRef={setContainerRef}\n            addresses={addresses}\n        >\n            {!!localTimezoneId && (\n                <AskUpdateTimezoneModal\n                    isOpen={isAskUpdateTimezoneModalOpen}\n                    onClose={() => setIsAskUpdateTimezoneModalOpen(false)}\n                    localTzid={localTimezoneId}\n                />\n            )}\n\n            <ContactEmailsProvider>\n                <InteractiveCalendarView\n                    view={view}\n                    isNarrow={isNarrow}\n                    isLoading={isLoading}\n                    tzid={tzid}\n                    {...timezoneInformation}\n                    displayWeekNumbers={displayWeekNumbers}\n                    displaySecondaryTimezone={displaySecondaryTimezone}\n                    weekStartsOn={weekStartsOn}\n                    inviteLocale={inviteLocale}\n                    now={utcNowDateInTimezone}\n                    date={utcDate}\n                    dateRange={utcDateRange}\n                    events={calendarsEvents}\n                    onClickDate={isNarrow ? handleChangeDate : handleClickDateWeekView}\n                    onChangeDate={handleChangeDate}\n                    isEventCreationDisabled={isEventCreationDisabled}\n                    onInteraction={(active: boolean) => setDisableCreate(active)}\n                    addresses={addresses}\n                    activeAddresses={activeAddresses}\n                    activeCalendars={activeCalendars}\n                    defaultCalendar={defaultCalendar}\n                    defaultCalendarBootstrap={defaultCalendarBootstrap}\n                    interactiveRef={interactiveRef}\n                    containerRef={containerRef}\n                    timeGridViewRef={timeGridViewRef}\n                    calendarsEventsCacheRef={calendarsEventsCacheRef}\n                    eventTargetActionRef={eventTargetActionRef}\n                />\n            </ContactEmailsProvider>\n        </CalendarContainerView>\n    );\n};\n\nexport default CalendarContainer;\n","import { useState, useEffect } from 'react';\n\ninterface Props {\n    refreshInterval: number;\n    tolerance: number;\n}\nconst useHasSuspendedCounter = ({ refreshInterval, tolerance }: Props) => {\n    const [counter, setCounter] = useState(0);\n\n    useEffect(() => {\n        let previousTime = Date.now();\n        let unmounted = false;\n\n        const intervalHandle = window.setInterval(() => {\n            const currentTime = Date.now();\n            const computedInterval = currentTime - previousTime;\n            const isOutOfSync = Math.abs(computedInterval - refreshInterval) > tolerance;\n            if (isOutOfSync && !unmounted) {\n                setCounter((counter) => counter + 1);\n            }\n            previousTime = currentTime;\n        }, refreshInterval);\n\n        return () => {\n            unmounted = true;\n            clearInterval(intervalHandle);\n        };\n    }, [refreshInterval, tolerance]);\n\n    return counter;\n};\n\nexport default useHasSuspendedCounter;\n","import { MutableRefObject, useEffect, useRef } from 'react';\nimport { c } from 'ttag';\nimport { useApi, useGetCalendarEventRaw, useHasSuspendedCounter } from '@proton/components';\nimport { fromUnixTime, differenceInMilliseconds } from 'date-fns';\nimport { getEvent as getEventRoute } from '@proton/shared/lib/api/calendars';\nimport { create } from '@proton/shared/lib/helpers/desktopNotification';\nimport { dateLocale } from '@proton/shared/lib/i18n';\nimport { CalendarAlarm, CalendarEvent } from '@proton/shared/lib/interfaces/calendar';\nimport { noop } from '@proton/shared/lib/helpers/function';\n\nimport { getAlarmMessage, getNextEventTime } from '@proton/shared/lib/calendar/alarms';\nimport { MINUTE } from '@proton/shared/lib/constants';\nimport notificationIcon from '../../../assets/notification.gif';\n\nimport { CalendarsEventsCache } from '../calendar/eventStore/interface';\n\nconst MIN_CUTOFF = -MINUTE;\n\nexport const displayNotification = ({ title = c('Title').t`Calendar alarm`, text = '', ...rest }) => {\n    return create(title, {\n        body: text,\n        icon: notificationIcon,\n        onClick() {\n            window.focus();\n        },\n        ...rest,\n    });\n};\n\nconst getFirstUnseenAlarm = (alarms: CalendarAlarm[] = [], set: Set<string>) => {\n    return alarms.find(({ ID }) => {\n        return !set.has(ID);\n    });\n};\n\ninterface Props {\n    alarms: CalendarAlarm[];\n    tzid: string;\n    calendarsEventsCacheRef: MutableRefObject<CalendarsEventsCache>;\n}\nconst AlarmWatcher = ({ alarms = [], tzid, calendarsEventsCacheRef }: Props) => {\n    const api = useApi();\n    const hasSuspendedCounter = useHasSuspendedCounter({ refreshInterval: MINUTE, tolerance: MINUTE / 2 });\n    const getCalendarEventRaw = useGetCalendarEventRaw();\n    const cacheRef = useRef<Set<string>>();\n\n    useEffect(() => {\n        let timeoutHandle = 0;\n        let unmounted = false;\n\n        const run = () => {\n            if (unmounted) {\n                return;\n            }\n            if (!cacheRef.current) {\n                cacheRef.current = new Set();\n            }\n\n            const firstUnseenAlarm = getFirstUnseenAlarm(alarms, cacheRef.current);\n            if (!firstUnseenAlarm) {\n                return;\n            }\n\n            const { ID, Occurrence, Trigger, CalendarID, EventID } = firstUnseenAlarm;\n\n            const nextAlarmTime = fromUnixTime(Occurrence);\n            const now = Date.now();\n            const diff = differenceInMilliseconds(nextAlarmTime, now);\n            const delay = Math.max(diff, 0);\n\n            const getEvent = () => {\n                const cachedEvent = calendarsEventsCacheRef.current.getCachedEvent(CalendarID, EventID);\n                if (cachedEvent) {\n                    return Promise.resolve(cachedEvent);\n                }\n                return api<{ Event: CalendarEvent }>({ ...getEventRoute(CalendarID, EventID), silence: true }).then(\n                    ({ Event }) => Event\n                );\n            };\n\n            timeoutHandle = window.setTimeout(() => {\n                if (unmounted || !cacheRef.current) {\n                    return;\n                }\n                // Eagerly add the event to seen, ignore if it would fail\n                cacheRef.current.add(ID);\n\n                // Ignore the event if it's in the past after the cutoff\n                if (diff < MIN_CUTOFF) {\n                    window.setTimeout(run, 0);\n                    return;\n                }\n\n                getEvent()\n                    .then((Event) => getCalendarEventRaw(Event))\n                    .then((eventRaw) => {\n                        if (unmounted) {\n                            return;\n                        }\n                        const { veventComponent: component } = eventRaw;\n                        // compute event start time based on trigger, as we cannot rely on dtstart for recurring events\n                        const start = new Date(getNextEventTime({ Occurrence, Trigger, tzid }));\n                        const now = new Date();\n                        const formatOptions = { locale: dateLocale };\n                        const text = getAlarmMessage({ component, start, now, tzid, formatOptions });\n                        return displayNotification({ text, tag: ID });\n                    })\n                    .catch(noop);\n\n                window.setTimeout(run, 0);\n            }, delay);\n        };\n\n        run();\n\n        return () => {\n            unmounted = true;\n            if (timeoutHandle) {\n                window.clearTimeout(timeoutHandle);\n            }\n        };\n    }, [alarms, tzid, getCalendarEventRaw, hasSuspendedCounter]);\n\n    return null;\n};\n\nexport default AlarmWatcher;\n","import { MutableRefObject } from 'react';\nimport { Calendar } from '@proton/shared/lib/interfaces/calendar';\nimport AlarmWatcher from './AlarmWatcher';\nimport useCalendarsAlarms from './useCalendarsAlarms';\nimport { CalendarsAlarmsCache } from './CacheInterface';\nimport { CalendarsEventsCache } from '../calendar/eventStore/interface';\n\ninterface Props {\n    calendars: Calendar[];\n    tzid: string;\n    calendarsAlarmsCacheRef: MutableRefObject<CalendarsAlarmsCache>;\n    calendarsEventsCacheRef: MutableRefObject<CalendarsEventsCache>;\n}\n\nconst AlarmContainer = ({ calendars, tzid, calendarsAlarmsCacheRef, calendarsEventsCacheRef }: Props) => {\n    const alarms = useCalendarsAlarms(calendars, calendarsAlarmsCacheRef);\n    return <AlarmWatcher alarms={alarms} tzid={tzid} calendarsEventsCacheRef={calendarsEventsCacheRef} />;\n};\n\nexport default AlarmContainer;\n","import { MutableRefObject, useEffect } from 'react';\nimport { LoaderPage, useNotifications, useApi, useCache } from '@proton/components';\nimport { useHistory } from 'react-router-dom';\nimport { c } from 'ttag';\nimport { getUnixTime } from 'date-fns';\nimport { Calendar, CalendarEvent } from '@proton/shared/lib/interfaces/calendar';\nimport { updateCalendar, getEvent } from '@proton/shared/lib/api/calendars';\nimport { getDateOrDateTimeProperty, propertyToUTCDate } from '@proton/shared/lib/calendar/vcalConverter';\nimport { loadModels } from '@proton/shared/lib/models/helper';\nimport { CalendarsModel } from '@proton/shared/lib/models';\nimport { MAXIMUM_DATE, MINIMUM_DATE } from '@proton/shared/lib/calendar/constants';\nimport { convertUTCDateTimeToZone, fromUTCDate, toUTCDate } from '@proton/shared/lib/date/timezone';\nimport { addMilliseconds, isSameDay } from '@proton/shared/lib/date-fns-utc';\nimport { getOccurrences } from '@proton/shared/lib/calendar/recurring';\nimport { VcalVeventComponent } from '@proton/shared/lib/interfaces/calendar/VcalModel';\nimport { getIsPropertyAllDay, getPropertyTzid } from '@proton/shared/lib/calendar/vcalHelper';\nimport getRecurrenceIdValueFromTimestamp from '@proton/shared/lib/calendar/getRecurrenceIdValueFromTimestamp';\nimport parseMainEventData from './event/parseMainEventData';\nimport { getRecurrenceIdDate } from './event/getEventHelper';\nimport { EventTargetAction } from './interface';\nimport { getCalendarEventStoreRecord } from './eventStore/cache/upsertCalendarEventStoreRecord';\nimport getAllEventsByUID from './getAllEventsByUID';\n\ninterface Props {\n    calendars: Calendar[];\n    tzid: string;\n    eventTargetActionRef: MutableRefObject<EventTargetAction | undefined>;\n}\nconst EventActionContainer = ({ tzid, calendars, eventTargetActionRef }: Props) => {\n    const { createNotification } = useNotifications();\n    const history = useHistory();\n    const api = useApi();\n    const cache = useCache();\n\n    useEffect(() => {\n        const run = async () => {\n            const params = new URLSearchParams(window.location.search);\n            const action = params.get('Action');\n\n            if (action === 'VIEW') {\n                const handleLinkError = () => {\n                    createNotification({\n                        type: 'error',\n                        text: c('Error').t`Invalid link to the event`,\n                    });\n                    history.replace('/');\n                };\n\n                const handleOtherError = () => {\n                    history.replace('/');\n                };\n\n                const handleGotoRange = (date: Date) => {\n                    history.replace(\n                        `/week/${[date.getUTCFullYear(), date.getUTCMonth() + 1, date.getUTCDate()].join('/')}`\n                    );\n                };\n\n                const handleGotoOccurrence = (\n                    eventData: CalendarEvent,\n                    eventComponent: VcalVeventComponent,\n                    occurrence: { localStart: Date; occurrenceNumber: number }\n                ) => {\n                    const { isAllDay, isAllPartDay } = getCalendarEventStoreRecord(eventComponent, eventData);\n\n                    const withOccurrenceDtstart = getDateOrDateTimeProperty(\n                        eventComponent.dtstart,\n                        occurrence.localStart\n                    );\n                    const utcDate = propertyToUTCDate(withOccurrenceDtstart);\n                    const startInTzid = toUTCDate(convertUTCDateTimeToZone(fromUTCDate(utcDate), tzid));\n                    eventTargetActionRef.current = {\n                        id: `${eventData.ID}-${occurrence.occurrenceNumber}`,\n                        isAllDay,\n                        isAllPartDay,\n                        startInTzid,\n                    };\n                    return handleGotoRange(startInTzid);\n                };\n\n                const handleGotoEvent = (eventData: CalendarEvent, eventComponent: VcalVeventComponent) => {\n                    const { isAllDay, isAllPartDay } = getCalendarEventStoreRecord(eventComponent, eventData);\n\n                    const utcDate = propertyToUTCDate(eventComponent.dtstart);\n                    const startInTzid = toUTCDate(convertUTCDateTimeToZone(fromUTCDate(utcDate), tzid));\n                    eventTargetActionRef.current = {\n                        id: eventData.ID,\n                        isAllDay,\n                        isAllPartDay,\n                        startInTzid,\n                    };\n                    return handleGotoRange(startInTzid);\n                };\n\n                const calendarID = params.get('CalendarID');\n                const eventID = params.get('EventID');\n                const recurrenceId = params.get('RecurrenceID');\n\n                if (!calendarID || !eventID) {\n                    return handleLinkError();\n                }\n                const calendar = calendars.find(({ ID }) => ID === calendarID);\n                if (!calendar) {\n                    return handleLinkError();\n                }\n                if (!calendar.Display) {\n                    await api({\n                        ...updateCalendar(calendarID, { Display: 1 }),\n                        silence: true,\n                    }).catch(() => {});\n                    await loadModels([CalendarsModel], { api, cache, useCache: false });\n                }\n                try {\n                    const result = await api<{ Event: CalendarEvent }>({\n                        ...getEvent(calendarID, eventID),\n                        silence: true,\n                    });\n                    const parsedEvent = parseMainEventData(result.Event);\n\n                    if (!parsedEvent) {\n                        throw new Error('Missing parsed event');\n                    }\n\n                    if (!parsedEvent.rrule) {\n                        return handleGotoEvent(result.Event, parsedEvent);\n                    }\n\n                    if (!recurrenceId) {\n                        const occurrences = getOccurrences({ component: parsedEvent, maxCount: 1 });\n                        if (!occurrences.length) {\n                            return handleLinkError();\n                        }\n                        const [firstOccurrence] = occurrences;\n                        return handleGotoOccurrence(result.Event, parsedEvent, firstOccurrence);\n                    }\n\n                    const parsedRecurrenceID = parseInt(recurrenceId || '', 10);\n\n                    if (\n                        !Number.isInteger(parsedRecurrenceID) ||\n                        parsedRecurrenceID < getUnixTime(MINIMUM_DATE) ||\n                        parsedRecurrenceID > getUnixTime(MAXIMUM_DATE)\n                    ) {\n                        return handleLinkError();\n                    }\n\n                    const eventsByUID = await getAllEventsByUID(api, calendarID, parsedEvent.uid.value);\n\n                    const { dtstart } = parsedEvent;\n                    const localRecurrenceID = toUTCDate(\n                        getRecurrenceIdValueFromTimestamp(\n                            parsedRecurrenceID,\n                            getIsPropertyAllDay(dtstart),\n                            getPropertyTzid(dtstart) || 'UTC'\n                        ).value\n                    );\n\n                    const isTargetOccurrenceEdited = eventsByUID.some((recurrence) => {\n       