ct<HTMLDivElement | null>;\n}\n\nconst useDropdownArrowNavigation = ({ rootRef }: Context) => {\n    const getDropdownMenuItems = () => {\n        if (!rootRef.current) {\n            return [];\n        }\n\n        return tabbable(rootRef.current, { includeContainer: false }).filter(\n            (elm) => !elm.dataset.preventArrowNavigation\n        );\n    };\n\n    const getFocusIndex = () => getDropdownMenuItems().findIndex((elm) => elm === document.activeElement);\n\n    const findElementAndFocus = (startingIndex: number) => {\n        const dropdownMenuItems = getDropdownMenuItems();\n\n        if (!dropdownMenuItems.length) {\n            return;\n        }\n\n        const lastIndex = dropdownMenuItems.length - 1;\n        let index = startingIndex;\n\n        /* loop from last to first item */\n        if (index > lastIndex) {\n            index = 0;\n        }\n        /* reverse loop from first to last item */\n        if (index < 0) {\n            index = lastIndex;\n        }\n\n        const elem = dropdownMenuItems[index] as any;\n\n        elem.focus();\n    };\n\n    const focusOnFirst = () => {\n        const index = 0;\n        findElementAndFocus(index);\n    };\n\n    const focusOnLast = () => {\n        const dropdownMenuItems = getDropdownMenuItems();\n        const index = dropdownMenuItems.length - 1;\n        findElementAndFocus(index);\n    };\n\n    const focusOnPrevious = () => {\n        const focusIndex = getFocusIndex();\n        findElementAndFocus(focusIndex - 1);\n    };\n\n    const focusOnNext = () => {\n        const focusIndex = getFocusIndex();\n        findElementAndFocus(focusIndex + 1);\n    };\n\n    const shortcutHandlers: HotkeyTuple[] = [\n        [\n            'ArrowUp',\n            (e) => {\n                e.preventDefault();\n                focusOnPrevious();\n            },\n        ],\n        [\n            ['Meta', 'ArrowUp'],\n            (e) => {\n                e.preventDefault();\n                focusOnFirst();\n            },\n        ],\n        [\n            'ArrowDown',\n            (e) => {\n                e.preventDefault();\n                focusOnNext();\n            },\n        ],\n        [\n            ['Meta', 'ArrowDown'],\n            (e) => {\n                e.preventDefault();\n                focusOnLast();\n            },\n        ],\n    ];\n\n    return {\n        shortcutHandlers,\n    };\n};\n\nexport default useDropdownArrowNavigation;\n","import { classnames } from './component';\n\nexport const getCustomSizingClasses = (style?: any) => {\n    if (!style) {\n        return '';\n    }\n    return classnames([\n        style['--height-custom'] !== undefined && 'h-custom',\n        style['--width-custom'] !== undefined && 'w-custom',\n        style['--top-custom'] !== undefined && 'top-custom',\n        style['--right-custom'] !== undefined && 'right-custom',\n        style['--left-custom'] !== undefined && 'left-custom',\n        style['--bottom-custom'] !== undefined && 'bottom-custom',\n    ]);\n};\n","import {\n    useEffect,\n    useState,\n    useRef,\n    CSSProperties,\n    useLayoutEffect,\n    AnimationEvent,\n    HTMLAttributes,\n    RefObject,\n    ReactNode,\n    MouseEvent as ReactMouseEvent,\n} from 'react';\nimport { c } from 'ttag';\nimport { noop } from '@proton/shared/lib/helpers/function';\nimport { dropdownRootClassName } from '@proton/shared/lib/busy';\nimport { useIsClosing, useCombinedRefs, useHotkeys, useDropdownArrowNavigation, HotkeyTuple } from '../../hooks';\nimport { classnames, getCustomSizingClasses } from '../../helpers';\nimport useRightToLeft from '../../containers/rightToLeft/useRightToLeft';\nimport { usePopper } from '../popper';\nimport { ALL_PLACEMENTS, Position } from '../popper/utils';\nimport Portal from '../portal/Portal';\n\nimport { useFocusTrap } from '../focus';\n\ninterface ContentProps extends HTMLAttributes<HTMLDivElement> {\n    ref?: RefObject<HTMLDivElement>;\n}\n\ninterface Props exten