AEI,KAAK,CAAEzB,KAAK,CAACI,IAFjB,CAGI,OAAO,CAAGA,IAAD,EAAkBH,QAAQ,gCAAMD,KAAN,MAAaI,IAAb,GAHvC,CAII,KAAK,CAAEvD,CAAC,CAAC,OAAD,CAAD,CAAW0F,CAAb,+EAJT,CAKI,WAAW,CAAE1F,CAAC,CAAC,aAAD,CAAD,CAAiB0F,CAAnB,sFALf,CAMI,cAAY,oDANhB,EAhDJ,CAwDKX,kBAAkB,eACf,aAAK,SAAS,CAAC,OAAf,wBACI,YAAK,SAAS,CAAC,sBAAf,UAAuC/E,CAAC,CAAC,OAAD,CAAD,CAAW0F,CAAlD,mFADJ,cAEI,KAAC,gBAAD,EAAkB,cAAc,CAAE1C,cAAlC,CAAkD,iBAAiB,CAAEC,iBAArE,EAFJ,GAzDR,GAdJ,cA6EI,MAAC,WAAD,yBACI,KAAC,MAAD,EAAQ,OAAO,CAAE2D,WAAjB,CAA8B,QAAQ,CAAE/C,UAAxC,UAAqD7D,CAAC,CAAC,QAAD,CAAD,CAAY0F,CAAjE,6EADJ,cAEI,KAAC,MAAD,EAAQ,KAAK,CAAC,MAAd,CAAqB,IAAI,CAAC,QAA1B,CAAmC,OAAO,CAAE7B,UAA5C,UAAyD7D,CAAC,CAAC,QAAD,CAAD,CAAY0F,CAArE,mFAFJ,GA7EJ,IADJ,CAoFH,CAxLD,CA0LA,cAAetD,CAAAA,YAAf","sourcesContent":["import { FormEvent, useState } from 'react';\nimport { c } from 'ttag';\nimport { createAddress } from '@proton/shared/lib/api/addresses';\nimport {\n    ADDRESS_TYPE,\n    DEFAULT_ENCRYPTION_CONFIG,\n    ENCRYPTION_CONFIGS,\n    MEMBER_PRIVATE,\n} from '@proton/shared/lib/constants';\nimport { Member, CachedOrganizationKey } from '@proton/shared/lib/interfaces';\nimport { requiredValidator } from '@proton/shared/lib/helpers/formValidators';\nimport { missingKeysMemberProcess, missingKeysSelfProcess } from '@proton/shared/lib/keys';\nimport { noop } from '@proton/shared/lib/helpers/function';\nimport { getAllMemberAddresses } from '@proton/shared/lib/api/members';\nimport {\n    SelectTwo,\n    Option,\n    ModalProps,\n    ModalTwo as Modal,\n    ModalTwoFooter as ModalFooter,\n    ModalTwoContent as ModalContent,\n    ModalTwoHeader as ModalHeader,\n    InputFieldTwo,\n    Button,\n    useFormErrors,\n    Loader,\n} from '../../components';\nimport {\n    useLoading,\n    useNotifications,\n    useEventManager,\n    useApi,\n    useAddresses,\n    usePremiumDomains,\n    useUser,\n    useAuthentication,\n    useGetUserKeys,\n} from '../../hooks';\n\nimport useAddressDomains from './useAddressDomains';\nimport SelectEncryption from '